hundredths <- function(text) as.integer(gsub(".", "", text, fixed = TRUE))
read_dataset <- function() {
  series <- list()
  for (line in readLines(file.path("input", "series.csv"), warn = FALSE)[-1L]) {
    parts <- strsplit(line, ",", fixed = TRUE)[[1L]]
    name <- parts[[1L]]
    point <- c(hundredths(parts[[2L]]), hundredths(parts[[3L]]))
    if (is.null(series[[name]])) series[[name]] <- matrix(integer(), 0L, 2L)
    series[[name]] <- rbind(series[[name]], point)
  }
  series <- lapply(series, function(points) points[order(points[, 1L]), , drop = FALSE])
  tests <- lapply(readLines(file.path("input", "test_points.csv"), warn = FALSE)[-1L], function(line) {
    parts <- strsplit(line, ",", fixed = TRUE)[[1L]]
    list(name = parts[[1L]], position = hundredths(parts[[2L]]))
  })
  settings <- list()
  for (line in readLines(file.path("input", "params.txt"), warn = FALSE)) {
    parts <- strsplit(line, " ", fixed = TRUE)[[1L]]
    settings[[parts[[1L]]]] <- parts[-1L]
  }
  for (key in c(
      "ROBUST_ITERATIONS",
      "CV_FOLDS",
      "GRID_POINTS",
      "BOOTSTRAP",
      "PLOT_SIZE"
  )) settings[[key]] <- as.integer(settings[[key]])
  for (key in c("BAND_Z", "OUTLIER_THRESHOLD")) settings[[key]] <- as.numeric(settings[[key]])
  list(series = series, tests = tests, settings = settings)
}

KAPPA <- c(epanechnikov = 0.75, biweight = 0.9375, triweight = 1.09375)
new_model <- function(...) list2env(list(...), parent = emptyenv())
kernel_fit <- function(positions, values, bandwidth, kernel, local_linear, diagnostics = TRUE) {
  model <- new_model(positions = positions, x = positions / 100, y = values, bandwidth = bandwidth,
                     kernel = kernel, local_linear = local_linear, fitted = NULL, leverage = NULL, edf = NULL,
                     cache = new.env(hash = TRUE, parent = emptyenv()))
  model$evaluate <- function(position) {
    key <- as.character(position)
    if (exists(key, envir = model$cache, inherits = FALSE)) return(model$cache[[key]])
    used <- which(abs(positions - position) < bandwidth)
    if (length(used) < (if (local_linear) 2L else 1L)) {
      result <- list(value = NULL, weights = NULL)
      model$cache[[key]] <- result
      return(result)
    }
    x0 <- position / 100
    h <- bandwidth / 100
    differences <- kernels <- numeric()
    for (i in used) {
      delta <- model$x[[i]] - x0
      u <- delta / h
      t <- 1 - u * u
      weight <- KAPPA[[kernel]] * t
      if (kernel != "epanechnikov") weight <- weight * t
      if (kernel == "triweight") weight <- weight * t
      differences <- c(differences, delta)
      kernels <- c(kernels, weight)
    }
    s0 <- ordered_sum(kernels)
    t0 <- ordered_sum(kernels * values[used])
    weights <- numeric(length(positions))
    if (local_linear) {
      s1 <- ordered_sum(kernels * differences)
      s2 <- ordered_sum(kernels * differences * differences)
      t1 <- ordered_sum(kernels * differences * values[used])
      determinant <- s0 * s2 - s1 * s1
      value <- (s2 * t0 - s1 * t1) / determinant
      weights[used] <- kernels * (s2 - s1 * differences) / determinant
    } else {
      value <- t0 / s0
      weights[used] <- kernels / s0
    }
    result <- list(value = value, weights = weights)
    model$cache[[key]] <- result
    result
  }
  model$estimate <- function(position) model$evaluate(position)$value
  model$weights <- function(position) model$evaluate(position)$weights
  if (diagnostics) {
    pairs <- lapply(positions, model$evaluate)
    if (!any(vapply(pairs, function(pair) is.null(pair$value), FALSE))) {
      model$fitted <- vapply(pairs, `[[`, 0, "value")
      model$leverage <- vapply(seq_along(pairs), function(i) pairs[[i]]$weights[[i]], 0)
      model$edf <- ordered_sum(model$leverage)
    }
  }
  model
}

median_value <- function(values) {
  ordered <- sort(values)
  middle <- length(ordered) %/% 2L
  if (length(ordered) %% 2L) ordered[[middle + 1L]] else (ordered[[middle]] + ordered[[middle + 1L]]) / 2
}
cholesky_lower <- function(matrix) {
  n <- nrow(matrix)
  lower <- matrix(0, n, n)
  for (row in seq_len(n)) {
    for (column in seq_len(row)) {
      sigma <- matrix[row, column]
      for (k in seq_len(column - 1L)) sigma <- sigma - lower[row, k] * lower[column, k]
      lower[row, column] <- if (row == column) sqrt(sigma) else sigma / lower[column, column]
    }
  }
  lower
}
solve_lower <- function(lower, right) {
  n <- length(right)
  intermediate <- solution <- numeric(n)
  for (row in seq_len(n)) {
    value <- right[[row]]
    for (k in seq_len(row - 1L)) value <- value - lower[row, k] * intermediate[[k]]
    intermediate[[row]] <- value / lower[row, row]
  }
  for (row in rev(seq_len(n))) {
    value <- intermediate[[row]]
    if (row < n) for (k in seq.int(row + 1L, n)) value <- value - lower[k, row] * solution[[k]]
    solution[[row]] <- value / lower[row, row]
  }
  solution
}
loess_fit <- function(positions, values, span, degree, iterations, diagnostics = TRUE) {
  model <- new_model(positions = positions, x = positions / 100, y = values, span = span, degree = degree,
                     rho = rep.int(1, length(positions)), records = list(), cache = new.env(
                         hash = TRUE,
                         parent = emptyenv()
                     ),
                     fitted = NULL, leverage = NULL, edf = NULL)
  model$local_fit <- function(position) {
    n <- length(positions)
    q <- (span * n) %/% 100L
    neighborhood <- order(abs(positions - position), seq_len(n), method = "radix")[seq_len(q)]
    distance <- max(abs(positions[neighborhood] - position))
    size <- degree + 1L
    matrix <- matrix(0, size, size)
    right <- numeric(size)
    rows <- list()
    for (i in sort(neighborhood)) {
      a <- abs(positions[[i]] - position) / distance
      s <- 1 - a * a * a
      weight <- s * s * s * model$rho[[i]]
      delta <- model$x[[i]] - position / 100
      basis <- if (degree == 1L) c(1, delta) else c(1, delta, delta * delta)
      rows[[length(rows) + 1L]] <- list(index = i, weight = weight, basis = basis)
      for (row in seq_len(size)) {
        right[[row]] <- right[[row]] + weight * basis[[row]] * values[[i]]
        for (column in seq_len(size)) matrix[row, column] <- matrix[
            row,
            column
        ] + weight * basis[[row]] * basis[[column]]
      }
    }
    lower <- cholesky_lower(matrix)
    beta <- solve_lower(lower, right)
    zeta <- solve_lower(lower, c(1, numeric(degree)))
    weights <- numeric(n)
    for (row in rows) weights[[row$index]] <- row$weight * ordered_sum(zeta * row$basis)
    list(value = beta[[1L]], zeta = zeta[[1L]], weights = weights)
  }
  model$evaluate <- function(position) {
    key <- as.character(position)
    if (!exists(key, envir = model$cache, inherits = FALSE)) model$cache[[key]] <- model$local_fit(position)
    model$cache[[key]]
  }
  model$estimate <- function(position) model$evaluate(position)$value
  model$weights <- function(position) model$evaluate(position)$weights
  if (diagnostics) {
    fits <- lapply(positions, model$local_fit)
    for (iteration in seq_len(iterations)) {
      residuals <- values - vapply(fits, `[[`, 0, "value")
      scale <- median_value(abs(residuals))
      for (i in seq_along(residuals)) {
        u <- residuals[[i]] / (6 * scale)
        v <- 1 - u * u
        model$rho[[i]] <- if (abs(u) < 1) v * v else 0
      }
      updated <- lapply(positions, model$local_fit)
      change <- max(abs(vapply(updated, `[[`, 0, "value") - vapply(fits, `[[`, 0, "value")))
      model$records[[length(model$records) + 1L]] <- list(
          iteration = iteration,
          scale = scale,
          zero_count = sum(model$rho == 0),
          change = change
      )
      fits <- updated
    }
    for (i in seq_along(positions)) model$cache[[as.character(positions[[i]])]] <- fits[[i]]
    model$fitted <- vapply(fits, `[[`, 0, "value")
    model$leverage <- model$rho * vapply(fits, `[[`, 0, "zeta")
    model$edf <- ordered_sum(model$leverage)
  }
  model
}

ordered_sum <- function(values) {
  total <- 0
  for (value in values) total <- total + value
  total
}
cross_validation_score <- function(observed, predicted) {
  if (any(vapply(predicted, is.null, FALSE))) return(NULL)
  estimates <- unlist(predicted, use.names = FALSE)
  ordered_sum((observed - estimates) * (observed - estimates)) / length(observed)
}
generalized_score <- function(observed, fitted, edf) {
  rss <- ordered_sum((observed - fitted) * (observed - fitted))
  factor <- 1 - edf / length(observed)
  rss / length(observed) / (factor * factor)
}
choose_candidate <- function(candidates) {
  eligible <- which(!vapply(candidates, function(candidate) is.null(candidate$score), FALSE))
  eligible[[which.min(vapply(candidates[eligible], function(candidate) candidate$score, 0))]]
}

spline_fit <- function(positions, values, penalty, diagnostics = TRUE) {
  x <- positions / 100
  h <- diff(x)
  size <- length(positions) - 2L
  a <- 1 / h[seq_len(size)]
  c <- 1 / h[seq.int(2L, size + 1L)]
  b <- -(a + c)
  diagonal <- vapply(
      seq_len(size),
      function(i) (h[[i]] + h[[i + 1L]]) / 3 + penalty * (a[[i]] * a[[i]] + b[[i]] * b[[i]] + c[[i]] * c[[i]]),
      0
  )
  first_band <- vapply(
      seq_len(size - 1L),
      function(i) h[[i + 1L]] / 6 + penalty * c[[i]] * (b[[i]] + b[[i + 1L]]),
      0
  )
  second_band <- vapply(seq_len(size - 2L), function(i) penalty * c[[i]] * c[[i + 1L]], 0)
  d <- l1 <- l2 <- numeric(size)
  for (i in seq_len(size)) {
    if (i >= 3L) l2[[i]] <- second_band[[i - 2L]] / d[[i - 2L]]
    if (i >= 2L) {
      correction <- if (i >= 3L) l2[[i]] * d[[i - 2L]] * l1[[i - 1L]] else 0
      l1[[i]] <- (first_band[[i - 1L]] - correction) / d[[i - 1L]]
    }
    value <- diagonal[[i]]
    if (i >= 2L) value <- value - l1[[i]] * l1[[i]] * d[[i - 1L]]
    if (i >= 3L) value <- value - l2[[i]] * l2[[i]] * d[[i - 2L]]
    d[[i]] <- value
  }
  model <- new_model(positions = positions, x = x, h = h, penalty = penalty, d = d, l1 = l1, l2 = l2,
                     fit = NULL, fitted = NULL, basis = NULL, leverage = NULL, edf = NULL)
  model$fit_values <- function(values) {
    n <- length(values)
    z <- numeric(size)
    for (i in seq_len(size)) {
      value <- (values[[i + 2L]] - values[[i + 1L]]) / h[[i + 1L]] - (values[[i + 1L]] - values[[i]]) / h[[i]]
      if (i >= 2L) value <- value - l1[[i]] * z[[i - 1L]]
      if (i >= 3L) value <- value - l2[[i]] * z[[i - 2L]]
      z[[i]] <- value
    }
    gamma <- numeric(n)
    for (i in rev(seq_len(size))) {
      value <- z[[i]] / d[[i]]
      if (i + 1L <= size) value <- value - l1[[i + 1L]] * gamma[[i + 2L]]
      if (i + 2L <= size) value <- value - l2[[i + 2L]] * gamma[[i + 3L]]
      gamma[[i + 1L]] <- value
    }
    omega <- numeric(n)
    omega[[1L]] <- (gamma[[2L]] - gamma[[1L]]) / h[[1L]]
    for (i in seq.int(
        2L,
        n - 1L
    )) omega[[i]] <- (gamma[[i + 1L]] - gamma[[i]]) / h[[i]] - (gamma[[i]] - gamma[[i - 1L]]) / h[[i - 1L]]
    omega[[n]] <- 0 - (gamma[[n]] - gamma[[n - 1L]]) / h[[n - 1L]]
    list(fitted = values - penalty * omega, gamma = gamma)
  }
  model$evaluate_fit <- function(fit, position) {
    fitted <- fit$fitted
    gamma <- fit$gamma
    x0 <- position / 100
    n <- length(positions)
    index <- which(positions >= position)[1L]
    if (!is.na(index) && positions[[index]] == position) return(fitted[[index]])
    if (!is.na(index) && index == 1L) {
      slope <- (fitted[[2L]] - fitted[[1L]]) / h[[1L]] - h[[1L]] * gamma[[2L]] / 6
      return(fitted[[1L]] - (x[[1L]] - x0) * slope)
    }
    if (is.na(index)) {
      slope <- (fitted[[n]] - fitted[[n - 1L]]) / h[[n - 1L]] + h[[n - 1L]] * gamma[[n - 1L]] / 6
      return(fitted[[n]] + (x0 - x[[n]]) * slope)
    }
    i <- index - 1L
    left <- x0 - x[[i]]
    right <- x[[i + 1L]] - x0
    (left * fitted[[i + 1L]] + right * fitted[[i]]) / h[[i]] - left * right * ((1 + left / h[[i]]) * gamma[[i + 1L]] + (1 + right / h[[i]]) * gamma[[i]]) / 6
  }
  model$prepare_basis <- function() {
    if (!is.null(model$basis)) return(invisible(NULL))
    n <- length(positions)
    model$basis <- lapply(seq_len(n), function(i) {
      unit <- numeric(n)
      unit[[i]] <- 1
      model$fit_values(unit)
    })
    model$leverage <- vapply(seq_len(n), function(i) model$basis[[i]]$fitted[[i]], 0)
    model$edf <- ordered_sum(model$leverage)
  }
  model$fit <- model$fit_values(values)
  model$fitted <- model$fit$fitted
  model$estimate <- function(position) model$evaluate_fit(model$fit, position)
  model$weights <- function(position) {
    model$prepare_basis()
    vapply(model$basis, function(fit) model$evaluate_fit(fit, position), 0)
  }
  if (diagnostics) model$prepare_basis()
  model
}
